<div class="customer-modal-backdrop jobcard-modal-backdrop"><section class="customer-modal jobcard-view-modal" role="dialog" aria-modal="true"><div class="customer-modal-header"><div><span class="modal-eyebrow"><?= e($job['job_card_no']) ?></span><h2><?= e($job['customer_name']) ?> <span class="job-status-pill"><?= e(strtoupper($job['status'])) ?></span></h2><span class="modal-code"><?= e($job['vehicle_number']?:'No vehicle') ?> · <?= e(trim(($job['make']?:'').' '.($job['model']?:''))) ?></span></div><a class="customer-modal-close" href="index.php?page=admin&amp;section=jobcards-<?= $job['status']==='completed'?'completed':($job['status']==='ongoing'?'ongoing':'pending') ?>">&times;</a></div><div class="customer-modal-body"><div class="job-modal-summary"><div><span>Customer</span><strong><?= e($job['customer_name']) ?></strong><small><?= e($job['contact_number']) ?><br><?= e($job['email']?:'') ?></small></div><div><span>Vehicle</span><strong><?= e($job['vehicle_number']?:'-') ?></strong><small><?= e($job['vehicle_type']?:'') ?> · <?= e(trim(($job['make']?:'').' '.($job['model']?:''))) ?><br><?= e($job['colour']?:'') ?> <?= $job['year']?'| '.(int)$job['year']:'' ?> <?= $job['current_mileage']?'| '.number_format((float)$job['current_mileage']).' KM':'' ?></small></div><div><span>Workshop</span><strong><?= e($job['bay_name']?:'No bay') ?></strong><small>Mechanic: <?= e($job['mechanic_name']?:'Not assigned') ?><br>Priority: <?= e(ucfirst($job['priority'])) ?></small></div></div><div class="job-modal-block"><h3>Job / Service Information</h3><div class="job-modal-copy"><strong>Complaint</strong><p><?= e($job['complaint']?:'-') ?></p><strong>Requested Work</strong><p><?= e($job['requested_work']?:'-') ?></p><strong>Notes</strong><p><?= e($job['notes']?:'-') ?></p></div></div><div class="job-modal-block"><h3>Parts / Labour <span class="service-count-badge"><?= count($job['items']) ?></span></h3><div class="table-responsive"><table class="table admin-table"><thead><tr><th>Type</th><th>Item / Service</th><th>Qty</th><th>Unit Price</th><th>Amount</th></tr></thead><tbody><?php if(!$job['items']): ?><tr><td colspan="5" class="empty-table">No items added.</td></tr><?php else: foreach($job['items'] as $item): ?><tr><td><?= e(ucfirst($item['item_type'])) ?></td><td><?= e($item['item_name']) ?></td><td><?= e((string)$item['quantity']) ?></td><td><?= number_format((float)$item['unit_price'],2) ?></td><td><?= number_format((float)$item['amount'],2) ?></td></tr><?php endforeach; endif; ?><tr><th colspan="4" class="text-end">Total</th><th>Rs. <?= number_format((float)$job['total_amount'],2) ?></th></tr></tbody></table></div></div></div><div class="customer-modal-footer job-modal-footer"><div><strong>Total: Rs. <?= number_format((float)$job['total_amount'],2) ?></strong></div><div class="job-view-actions-inline"><?php if($job['status']==='pending'): ?><form method="post" action="index.php?page=admin&amp;section=jobcards-action"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="job_card_id" value="<?= (int)$job['id'] ?>"><input type="hidden" name="action" value="start"><button class="btn btn-primary">▷ Start Job</button></form><?php elseif($job['status']==='ongoing'): ?><form method="post" action="index.php?page=admin&amp;section=jobcards-action"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="job_card_id" value="<?= (int)$job['id'] ?>"><input type="hidden" name="action" value="complete"><button class="btn btn-success">Mark as Completed</button></form><?php endif; ?><?php if($job['status']!=='completed'&&$job['status']!=='cancelled'): ?><form method="post" action="index.php?page=admin&amp;section=jobcards-action" onsubmit="return confirm('Cancel this job card?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="job_card_id" value="<?= (int)$job['id'] ?>"><input type="hidden" name="action" value="cancel"><button class="btn btn-light">Cancel</button></form><?php endif; ?><a class="btn btn-light" href="index.php?page=admin&amp;section=jobcards-<?= $job['status']==='completed'?'completed':($job['status']==='ongoing'?'ongoing':'pending') ?>">Close</a></div></div></section></div>
